mapper.insert:
INSERT IGNORE INTO chartbook (
    id, owner_key, name, status, create_idempotency_key, created_at, updated_at
) VALUES (
    #{id}, #{ownerKey}, #{name}, 'ACTIVE', #{idempotencyKey}, #{createdAt}, #{createdAt}
)

mapper.select:
SELECT link.material_id FROM material_scope_link link
JOIN material m ON m.id = link.material_id AND m.owner_key = #{ownerKey}
JOIN chartbook c ON c.id = link.scope_key AND c.owner_key = #{ownerKey}
WHERE link.scope_type = 'CHARTBOOK' AND link.scope_key = #{chartbookId}
ORDER BY link.created_at, link.material_id
